import XCTest
@testable import Mihomo

/// fix/nc-jq-full: the native jq interpreter (PacketTunnel/NativeMitM/Rewrite/NativeJQ*.swift).
///
/// NativeCoreJQFixtures.json is generated by work/nc/jqfull/gen_fixtures.py with the real jq CLI (`jq -c`) as the
/// oracle: language features + builtins, and the filters of real "JQ版" modules verbatim (ddgksf2013 TieBa / Goofish /
/// NeteaseMail, QingRex LoonKissSurge Reddit walk(), 京东, 滴滴, 中华万年历, 驾校一点通) on realistic bodies. Every case
/// must give byte-identical compact outputs, and fail exactly where jq fails (compile errors included).
final class NativeCoreJQTests: XCTestCase {

    struct Case: Decodable {
        var name: String
        var filter: String
        var input: String
        var outputs: [String]
        var error: String?
        var module: String?
    }

    struct Fixtures: Decodable {
        var oracle: String
        var cases: [Case]
    }

    private func fixtures() throws -> Fixtures {
        let bundle = Bundle(for: NativeCoreJQTests.self)
        guard let url = bundle.url(forResource: "NativeCoreJQFixtures", withExtension: "json") else {
            XCTFail("NativeCoreJQFixtures.json missing from the test bundle")
            return Fixtures(oracle: "", cases: [])
        }
        return try JSONDecoder().decode(Fixtures.self, from: Data(contentsOf: url))
    }

    /// Runs one case; nil when it matches the oracle, else a description of the mismatch.
    static func check(_ c: Case) -> String? {
        let prog: NativeJQ.Program
        do {
            prog = try NativeJQ.compile(c.filter)
        } catch {
            return c.error == "COMPILE" ? nil : "\(c.name): compile failed (\(error)), jq did not"
        }
        if c.error == "COMPILE" { return "\(c.name): compiled, jq rejects it at compile time" }
        let input: JQValue
        do { input = try JQJSONParser.parse(c.input) } catch { return "\(c.name): input did not parse (\(error))" }
        let r = NativeJQ.runAll(prog, input: input)
        let got = r.outputs.map { JQOut.dump($0) }
        if got != c.outputs {
            return "\(c.name): outputs differ\n  jq:     \(c.outputs.joined(separator: " | ").prefix(800))\n  native: \(got.joined(separator: " | ").prefix(800))"
        }
        if (r.error == nil) != (c.error == nil) {
            return "\(c.name): error mismatch — jq: \(c.error ?? "none"), native: \(r.error ?? "none")"
        }
        return nil
    }

    func testOracleFixtures() throws {
        let f = try fixtures()
        XCTAssertGreaterThan(f.cases.count, 150)
        let fails = f.cases.compactMap(Self.check)
        XCTAssertEqual(fails, [], fails.joined(separator: "\n"))
    }

    func testRealModulesCovered() throws {
        let f = try fixtures()
        let mods = Set(f.cases.compactMap(\.module))
        for m in ["TieBaAds", "GoofishAds", "NeteaseMailAds", "Reddit", "JD", "DiDi", "Etouch", "JiaXiao"] {
            XCTAssertTrue(mods.contains(m), "no fixture for module \(m)")
        }
        let fails = f.cases.filter { $0.module != nil }.compactMap(Self.check)
        XCTAssertEqual(fails, [], fails.joined(separator: "\n"))
    }

    func testPreludeParses() {
        // a parse error in the prelude would silently drop every jq-defined builtin
        XCTAssertGreaterThan(JQPrelude.defs.count, 50)
        for key in ["map/1", "select/1", "walk/1", "with_entries/1", "paths/0", "del/1", "IN/1", "any/2", "splits/1"] {
            XCTAssertNotNil(JQPrelude.defs[key], key)
        }
        for (key, d) in JQPrelude.defs {
            var sc = JQScope(nil, nil)
            for p in d.params {
                if p.isVar { sc = JQScope(sc, .variable(p.name)) }
                sc = JQScope(sc, .fn("\(p.name)/0"))
            }
            XCTAssertNoThrow(try JQResolver.resolve(d.body, sc), "prelude \(key) does not resolve")
        }
    }

    func testBodyApply() {
        let prog = try! NativeJQ.compile(".data |= del(.ads) | .n += 1")
        guard case .body(let out) = NativeJQ.apply(prog, body: Data(#"{"n":1.50,"data":{"ads":[1],"keep":"é"},"z":true}"#.utf8)) else {
            return XCTFail("jq did not apply")
        }
        XCTAssertEqual(String(decoding: out, as: UTF8.self), #"{"n":2.5,"data":{"keep":"é"},"z":true}"#)
        // literal numbers and key order survive untouched parts
        let id = try! NativeJQ.compile(".")
        guard case .body(let same) = NativeJQ.apply(id, body: Data(#"{"b":1.000,"a":1e2}"#.utf8)) else { return XCTFail() }
        XCTAssertEqual(String(decoding: same, as: UTF8.self), #"{"b":1.000,"a":1E+2}"#)
        // not JSON / runtime error / no output: skip (the caller passes the body through)
        if case .body = NativeJQ.apply(prog, body: Data("<html>".utf8)) { XCTFail("non-JSON body rewritten") }
        if case .body = NativeJQ.apply(try! NativeJQ.compile(".a.b"), body: Data(#"{"a":1}"#.utf8)) { XCTFail("error rewrote") }
        if case .body = NativeJQ.apply(try! NativeJQ.compile("empty"), body: Data("{}".utf8)) { XCTFail("empty rewrote") }
    }

    func testBudget() {
        let prog = try! NativeJQ.compile("[repeat(1)] | length")
        let t0 = Date()
        guard case .failed(let why) = NativeJQ.run(prog, input: .null, budget: 0.2) else { return XCTFail("endless filter finished") }
        XCTAssertTrue(why.contains("budget") || why.contains("deep"), why)
        XCTAssertLessThan(Date().timeIntervalSince(t0), 3)
    }

    func testDeepRecursionOnBigStack() throws {
        func nested(_ n: Int) -> Data {
            var s = ""
            for _ in 0..<n { s += #"{"a":"# }
            s += "1"
            for _ in 0..<n { s += "}" }
            return Data(s.utf8)
        }
        let prog = try NativeJQ.compile(#"walk(if type == "number" then . + 1 else . end) | [paths] | length"#)
        guard case .body(let out) = NativeJQ.apply(prog, body: nested(100), budget: 10) else { return XCTFail("100-deep walk failed") }
        XCTAssertEqual(String(decoding: out, as: UTF8.self), "100")
        // far deeper than any body: a clean "too deep" skip (stack guard), never a crash
        for n in [1500, 5000] {
            if case .skip(let why) = NativeJQ.apply(prog, body: nested(n), budget: 10) {
                XCTAssertTrue(why.contains("deep") || why.contains("depth") || why.contains("budget"), why)
            }
        }
    }

    func testCompileErrors() {
        for bad in ["", ".a | | .b", "foo_bar_baz", "$x", "break $nope", ".a as [$x] ?// $x | 1", "@nosuchformat \"x\"", "import \"a\" as a; ."] {
            XCTAssertThrowsError(try NativeJQ.compile(bad), bad)
        }
    }

    // MARK: rule integration

    private func rule(_ json: String) -> NativeBodyRule? {
        guard let r = try? JSONDecoder().decode(RWSnapRule.self, from: Data(json.utf8)) else { return nil }
        return NativeBodyRule(r)
    }

    func testNativeBodyRuleRunsFullJQ() {
        let filter = #"walk(if type == "object" then del(.ad) else . end) | .list |= map(select(.keep))"#
        let enc = String(data: try! JSONEncoder().encode(filter), encoding: .utf8)!
        guard let r = rule(#"{"i":3,"kind":"jq","phase":"response","bodyOK":true,"jqx":\#(enc)}"#) else {
            return XCTFail("rule not built")
        }
        let body = Data(#"{"list":[{"keep":true,"ad":1},{"keep":false}],"ad":{"x":1},"v":"1.0"}"#.utf8)
        guard case .body(let out) = r.apply(body) else { return XCTFail("not applied") }
        XCTAssertEqual(String(decoding: out, as: UTF8.self), #"{"list":[{"keep":true}],"v":"1.0"}"#)
        // runtime error: skipped, never handed back
        guard case .skipped = r.apply(Data(#"{"list":3}"#.utf8)) else { return XCTFail("error not skipped") }
        guard case .skipped = r.apply(Data("not json".utf8)) else { return XCTFail("non-JSON not skipped") }
        // a filter that does not compile: no rule (the engine skips it with a note)
        XCTAssertNil(rule(#"{"i":4,"kind":"jq","phase":"response","bodyOK":true,"jqx":".a | | ."}"#))
    }

    func testResponseExecKeepsBodyOnSkip() {
        guard let r = rule(#"{"i":1,"kind":"jq","phase":"response","bodyOK":true,"jqx":".a.b = 1"}"#) else { return XCTFail() }
        let raw = Data(#"{"a":5}"#.utf8)
        let res = NativeBodyExec.response([.body(r)], status: 200, headers: [["Content-Type", "application/json"], ["Content-Length", "\(raw.count)"]],
                                          length: Int64(raw.count), raw: raw)
        guard case .native(let resp) = res else { return XCTFail("handed back") }
        XCTAssertEqual(resp.body, raw)
        XCTAssertEqual(resp.rules, [])
    }

    // MARK: module formats

    private func jqRules(_ text: String) -> [NCEngineRule] {
        let rs = NCEngineRuleset()
        rs.parseText(text, source: "模块", args: [:])
        return rs.rules.filter { $0.kind == "jq" }
    }

    func testModuleFormats() {
        let surge = jqRules("""
        #!name=jq
        [Body Rewrite]
        http-response-jq ^https://a\\.example\\.com/x '.data |= del(.ads)'
        http-request-jq ^https://a\\.example\\.com/y jq-path="https://example.com/f.jq"
        """)
        XCTAssertEqual(surge.count, 2)
        XCTAssertEqual(surge.first?.phase, "response")
        XCTAssertEqual(surge.first?.jq, ".data |= del(.ads)")
        XCTAssertEqual(surge.last?.phase, "request")
        XCTAssertEqual(surge.last?.data, "https://example.com/f.jq")

        let loon = jqRules("""
        #!name=jq
        [Rewrite]
        ^https://b\\.example\\.com/x response-body-json-jq '.a = 1'
        ^https://b\\.example\\.com/y request-body-json-jq jq-path="https://example.com/g.jq"
        """)
        XCTAssertEqual(loon.count, 2)
        XCTAssertEqual(loon.first?.phase, "response")
        XCTAssertEqual(loon.first?.jq, ".a = 1")
        XCTAssertEqual(loon.last?.phase, "request")
        XCTAssertEqual(loon.last?.data, "https://example.com/g.jq")

        let qx = jqRules("""
        [rewrite_local]
        ^https?:\\/\\/tieba\\.baidu\\.com\\/c\\/f\\/forum\\/forumGuide url jsonjq-response-body '.hot_search = []'
        """)
        XCTAssertEqual(qx.count, 1)
        XCTAssertEqual(qx.first?.jq, ".hot_search = []")

        let egern = jqRules("""
        name: jq
        body_rewrites:
        - response_jq:
            match: ^https://api\\.bilibili\\.com/pgc/view/v2/app/season\\?
            filter: del(.data.payment)
        - request_jq:
            match: ^https://c\\.example\\.com/
            filter: https://example.com/r.jq
        mitm:
          hostnames:
            includes:
            - api.bilibili.com
        """)
        XCTAssertEqual(egern.count, 2)
        XCTAssertEqual(egern.first?.phase, "response")
        XCTAssertEqual(egern.first?.jq, "del(.data.payment)")
        XCTAssertEqual(egern.last?.phase, "request")
        XCTAssertEqual(egern.last?.data, "https://example.com/r.jq")
        // published modules repeat the phase token: "http-response-jq http-response ^regex '<filter>'"
        let stray = jqRules("""
        #!name=jq
        [Body Rewrite]
        http-response-jq http-response ^https:\\/\\/api\\.ksedt\\.com\\/api\\/config\\/ 'delpaths([["result","homead"]])'
        """)
        XCTAssertEqual(stray.count, 1)
        XCTAssertEqual(stray.first?.pattern, #"^https:\/\/api\.ksedt\.com\/api\/config\/"#)
        XCTAssertEqual(stray.first?.jq, #"delpaths([["result","homead"]])"#)
        for r in surge + loon + qx + egern + stray where !r.jq.isEmpty {
            XCTAssertNoThrow(try NativeJQ.compile(r.jq), r.jq)
        }
    }
}
